dslRule:
/*!
@id: eclipse.collections.array-to-collectionsutil-ipath
@description: Replace List.toArray(new String[size]) with CollectionsUtil.toArray(List, IPath.class) for lists of IPath objects.
@severity: WARNING
*/
$list.toArray(new java.lang.String[$list.size()]) :: instanceof($list, "java.util.List") && genericTypeIs($list, 0, "org.eclipse.core.runtime.IPath")
=>
org.eclipse.jdt.internal.corext.util.CollectionsUtil.toArray($list, org.eclipse.core.runtime.IPath.class)
;;

beforeExample:
import java.util.ArrayList;
import java.util.List;
import org.eclipse.core.runtime.IPath;
import org.eclipse.core.runtime.Path;

public class Example {
    private IPath[] fInstallLocations;
    public void setup() {
        List<IPath> locations = new ArrayList<>();
        locations.add(Path.fromOSString("/path/to/jre1"));
        locations.add(Path.fromOSString("/path/to/jre2"));
        fInstallLocations = locations.toArray(new String[locations.size()]);
    }
}

