import java.util.ArrayList;
import java.util.List;
import org.eclipse.core.runtime.IPath;
import org.eclipse.core.runtime.Path;
import org.eclipse.jdt.internal.corext.util.CollectionsUtil;

public class Example {
    private IPath[] fInstallLocations;
    public void setup() {
        List<IPath> locations = new ArrayList<>();
        locations.add(Path.fromOSString("/path/to/jre1"));
        locations.add(Path.fromOSString("/path/to/jre2"));
        fInstallLocations = CollectionsUtil.toArray(locations, IPath.class);
    }
}

